 const home=<><View style={S.hero}><Text style={S.heroTop}>✦  SEU MOVIMENTO COMEÇA AQUI</Text><Text style={S.heroText}>VAI LÁ.{ '\n'}FAZ VALER.</Text><Text style={S.heroSub}>Uma série de cada vez. O seu treino, ilustrado por Josperd.</Text><Btn text="COMEÇAR TREINO A   →" onPress={()=>setTab('A')}/><Image source={FILES[state.persona==='loira'?'lateral_loira.png':'frontal_vinho.png']} style={S.heroPoster} resizeMode="cover"/><View style={S.heroTag}><Text style={S.heroTagText}>BORA!</Text></View></View><SectionTitle over="Sua companhia" title="Escolha o personagem" desc="Josperd ou Camila. Troque quando quiser."/>{personaSelect(true)}<View style={S.statsRow}><View style={S.stat}><Text style={S.statBig}>{state.sessions.length}</Text><Text style={S.statLabel}>Treinos</Text></View><View style={S.stat}><Text style={S.statBig}>{state.sessions.reduce((a,x)=>a+x.sets,0)}</Text><Text style={S.statLabel}>Séries feitas</Text></View><View style={S.stat}><Text style={S.statBig}>{streakDays(state.sessions,today())}</Text><Text style={S.statLabel}>Dias seguidos</Text></View></View><SectionTitle over="Dupla da semana" title="Escolha seu treino"/>{(['A','B'] as const).map(t=><Pressable onPress={()=>setTab(t)} key={t} style={[S.workoutTile,t==='A'?{backgroundColor:'#e9a0bf'}:{backgroundColor:'#abc8fa'}]}><View style={{zIndex:2,flex:1}}><Text style={S.workoutOver}>FICHA {t} · {t==='A'?'06':'08'} EXERCÍCIOS</Text><Text style={S.workoutBig}>TREINO {t}</Text><Text style={S.workoutSub}>{t==='A'?'Bíceps, costas e trapézio':'Bíceps, peito e ombro'}</Text><Text style={S.workoutLink}>ABRIR TREINO  ↗</Text></View><Image source={FILES[t==='A'?(state.persona==='loira'?'martelo_loira.png':'martelo_vinho.png'):(state.persona==='loira'?'crucifixo_loira.png':'supino_vinho.png')]} style={S.workoutArt}/></Pressable>)}</>;
 const workout=(t:'A'|'B')=><><SectionTitle over={`FICHA ${t} / ${t==='A'?'01':'02'}`} title={`Treino ${t}`} desc={t==='A'?'Bíceps, costas e trapézio':'Bíceps, peito e ombro'}/>{guidedPanel(t)}<View style={S.settingBox}><Text style={S.settingTitle}>✦ PREPARE O TREINO</Text><Text style={S.muted}>Escolha quantas séries fará antes de começar. Toque em +/− ou abra o exercício para editar também peso e repetições.</Text>{EXERCISES.filter(x=>x.treino===t).map(ex=>{const q=state.override[ex.id]||ex;return <View key={ex.id} style={{flexDirection:'row',justifyContent:'space-between',alignItems:'center',gap:10,borderTopWidth:1,borderTopColor:'#e5e2da',paddingVertical:9}}><Text style={{flex:1,fontSize:11,fontWeight:'800',color:P.ink}}>{ex.nome}</Text><Pressable onPress={()=>adjustSeries(ex,-1)} accessibilityLabel={`Diminuir séries de ${ex.nome}`} style={[S.check,{backgroundColor:P.yellow}]}><Text style={S.checkTxt}>−</Text></Pressable><Text style={{minWidth:19,textAlign:'center',fontWeight:'900',color:P.ink}}>{q.series}</Text><Pressable onPress={()=>adjustSeries(ex,1)} accessibilityLabel={`Aumentar séries de ${ex.nome}`} style={[S.check,{backgroundColor:P.yellow}]}><Text style={S.checkTxt}>+</Text></Pressable></View>})}</View><View style={S.progress}><Text style={S.progressOver}>SÉRIES MARCADAS HOJE</Text><Text style={S.progressNumber}>{progress(t)}%</Text><Text style={S.progressSub}>{marked(t)} de {count(t)} séries</Text><View style={S.track}><View style={[S.fill,{width:`${progress(t)}%`}]}/></View></View>{[...new Set(EXERCISES.filter(e=>e.treino===t).map(e=>e.grupo))].map(group=><View key={group}><Text style={S.group}>{group.toUpperCase()}</Text>{EXERCISES.filter(e=>e.treino===t&&e.grupo===group).map(e=>{const c=state.override[e.id]||e;const status=imageInfo(e,state.persona);return <View key={e.id} style={S.exercise}><Pressable onPress={()=>startEdit(e)} accessibilityLabel={`Ver detalhes de ${e.nome}`}>{art(e)}</Pressable><View style={S.exerciseInfo}><Text style={S.exerciseCode}>{e.codigo} / {e.grupo.toUpperCase()}</Text><Text style={S.exerciseName}>{e.nome}</Text><Text style={S.exerciseMeta}>{c.series} × {c.reps}  ·  {c.peso?`${c.peso} kg`:'peso a definir'}</Text>{status.status!=='ok'&&<Text style={[S.fallbackNote,status.status==='missing'&&{color:'#a94865'}]}>{status.note}</Text>}<View style={S.checks}>{Array.from({length:Math.max(1,Math.min(12,c.series))},(_,i)=><Pressable key={i} onPress={()=>toggle(e,i)} accessibilityLabel={`Série ${i+1} de ${e.nome}`} hitSlop={4} accessibilityRole="checkbox" accessibilityState={{checked:!!done(e)[i]}} aria-checked={!!done(e)[i]} style={[S.check,done(e)[i]&&S.checkOn]}><Text style={S.checkTxt}>{done(e)[i]?'✓':i+1}</Text></Pressable>)}</View><Pressable onPress={()=>startEdit(e)}><Text style={S.editLink}>VER ARTE / EDITAR  ↗</Text></Pressable></View></View>})}</View>)}<Text style={S.disclaimer}>As séries do Treino B são provisórias e editáveis. Ilustrações não substituem supervisão profissional.</Text><Btn text={`FINALIZAR TREINO ${t}    ✓`} onPress={()=>finish(t)} disabled={marked(t)===0}/></>;
 const records=annotateRecords(state.sessions),bests=Object.entries(personalBests(state.sessions)).sort((x,y)=>y[1].peso-x[1].peso),volume=totalVolume(state.sessions);
 const history=<><SectionTitle over="Arquivo pessoal" title="Seu histórico" desc="A constância faz parte da jornada."/><View style={S.statsRow}><View style={S.stat}><Text style={S.statBig}>{state.sessions.length}</Text><Text style={S.statLabel}>Treinos</Text></View><View style={S.stat}><Text style={S.statBig}>{state.sessions.reduce((a,x)=>a+x.sets,0)}</Text><Text style={S.statLabel}>Séries concluídas</Text></View><View style={S.stat}><Text style={S.statBig}>{streakDays(state.sessions,today())}</Text><Text style={S.statLabel}>Dias seguidos</Text></View></View>{(bests.length>0||volume>0)&&<View style={S.records}><Text style={S.recordsOver}>✦ SEUS NÚMEROS</Text><Text style={S.recordsTitle}>CARGAS E RECORDES</Text>{volume>0&&<Text style={S.recordsVol}>{fmtKg(volume)} kg <Text style={S.recordsVolSub}>de volume total</Text></Text>}{bests.map(([id,r])=><View key={id} style={S.recordRow}><Text style={S.recordName}>{r.nome}</Text><Text style={S.recordKg}>{fmtKg(r.peso)} kg</Text></View>)}<Text style={S.recordsNote}>Maior carga registrada por exercício. Volume = séries × repetições × carga, só das séries marcadas.</Text></View>}{state.sessions.length?<>{state.sessions.map((x,i)=>({x,i})).reverse().map(({x,i})=>{const open=openSession===i,items=x.items||[];return <View style={S.historyWrap} key={`${x.date}-${x.treino}-${i}`}><Pressable accessibilityRole="button" accessibilityState={{expanded:open}} aria-expanded={open} accessibilityLabel={`Treino ${x.treino}, ${x.date.split('-').reverse().join('/')}, ${x.sets} séries. Toque para ${open?'recolher':'ver o detalhe'}`} onPress={()=>setOpenSession(open?null:i)} style={S.historyHead}><View style={{flex:1}}><Text style={S.historyTitle}>TREINO {x.treino}  ★{records[i].length>0&&<Text style={S.badge}>  ★ RECORDE</Text>}</Text><Text style={S.muted}>{x.date.split('-').reverse().join('/')} · {x.time} · {x.sets} séries{x.volume?` · ${fmtKg(x.volume)} kg`:''}</Text></View><Text style={S.historyPercent}>{x.percent}%</Text></Pressable>{open&&<View style={S.historyItems}>{items.length?items.map(it=><View key={it.id} style={S.itemRow}><Text style={S.itemName}>{it.nome}{records[i].includes(it.id)?'  ★':''}</Text><Text style={S.itemMeta}>{it.series} × {it.reps} · {it.peso?`${fmtKg(it.peso)} kg`:'sem carga'}</Text></View>):<Text style={S.muted}>Treino registrado sem detalhe por exercício.</Text>}</View>}</View>})}<Btn subtle text="EXPORTAR PLANILHA (CSV)" onPress={exportCsv}/></>:<View style={S.empty}><Text style={{fontSize:45}}>✦</Text><Text style={S.headingTitle}>O PRIMEIRO VEM AÍ.</Text><Text style={S.muted}>Finalize um treino para iniciar seu histórico.</Text><Btn text="IR PARA TREINO A →" onPress={()=>setTab('A')}/></View>}</>;
 const gallery=<><SectionTitle over="Arte por Josperd" title="Coleção ilustrada" desc="Selecione a personagem. Quando faltar a arte da Camila, aparece a versão do Josperd com aviso."/>{personaSelect(true)}<View style={S.filterRow}>{(['ALL','A','B'] as const).map(x=><Pressable key={x} onPress={()=>setGalleryFilter(x)} style={[S.filter, galleryFilter===x&&{backgroundColor:P.navy}]}><Text style={[S.filterText,galleryFilter===x&&{color:P.white}]}>{x==='ALL'?'TODOS':`TREINO ${x}`}</Text></Pressable>)}</View><View style={S.galleryGrid}>{EXERCISES.filter(e=>galleryFilter==='ALL'||e.treino===galleryFilter).map(e=><Pressable key={e.id} onPress={()=>startEdit(e)} style={S.galleryCard}>{art(e,true)}<Text style={S.galleryCode}>{e.codigo} · {e.grupo}</Text><Text style={S.galleryTitle}>{e.nome}</Text></Pressable>)}</View><Text style={S.disclaimer}>Na polia baixa frontal ainda não existe imagem específica: o Josperd é apenas uma capa decorativa.</Text></>;
 const settings=<><SectionTitle over="Personalização" title="O seu modo" desc="Este é seu espaço. Sem conta, sem anúncios."/><Text style={S.group}>PERSONAGEM</Text>{personaSelect()}<Text style={S.group}>DESCANSO ENTRE SÉRIES</Text><View style={S.filterRow}>{[30,45,60,90,120,180].map(n=><Pressable key={n} onPress={()=>update(s=>({...s,rest:n}))} style={[S.filter,{marginBottom:8},state.rest===n&&{backgroundColor:P.navy}]}><Text style={[S.filterText,state.rest===n&&{color:P.white}]}>{n}s</Text></Pressable>)}</View><View style={S.settingBox}><Text style={[S.group,{marginTop:0}]}>TELA DURANTE O TREINO</Text><Text style={S.muted}>Evita que a tela apague enquanto você está nos Treinos A ou B. Desligado por padrão para poupar bateria.</Text><Pressable accessibilityRole="switch" accessibilityState={{checked:state.keepAwake}} aria-checked={state.keepAwake} style={S.soundSwitch} onPress={()=>update(v=>({...v,keepAwake:!v.keepAwake}))}><Text style={S.settingTitle}>MANTER TELA LIGADA</Text><Text style={S.soundState}>{state.keepAwake?'SIM ✓':'NÃO'}</Text></Pressable></View><View style={[S.settingBox,{borderWidth:2,borderColor:P.navy,backgroundColor:'#fdfdfc'}]}><Text style={[S.group,{marginTop:0}]}>BIBLIOTECA DE SONS ♫</Text><Text style={S.muted}>Tudo desligado por padrão. Escolha quais avisos deseja ouvir — sem interferir na música das fitas.</Text><Pressable style={S.soundSwitch} onPress={()=>update(v=>({...v,sounds:{...(v.sounds||DEFAULT_SOUNDS),enabled:!v.sounds?.enabled}}))}><Text style={S.settingTitle}>ATIVAR EFEITOS SONOROS</Text><Text style={S.soundState}>{state.sounds?.enabled?'ATIVO ✓':'DESLIGADO'}</Text></Pressable><Text style={S.inputLabel}>ESTILO DE SOM</Text><View style={S.filterRow}>{SOUND_STYLES.map(([id,name,description])=><View key={id} style={[S.soundPack,state.sounds?.pack===id&&{borderColor:P.ink,backgroundColor:'#fff1d9'}]}><Pressable onPress={()=>update(v=>({...v,sounds:{...v.sounds,pack:id}}))}><Text style={S.soundPackName}>{name}</Text><Text style={S.muted}>{description}</Text></Pressable><Pressable style={S.previewBtn} onPress={()=>playSound('series',true,id)}><Text style={S.editLink}>▶ TESTAR</Text></Pressable></View>)}</View><Text style={S.inputLabel}>VOLUME · {state.sounds?.volume??35}%</Text><View style={S.filterRow}><Pressable style={S.filter} onPress={()=>update(v=>({...v,sounds:{...v.sounds,volume:Math.max(0,v.sounds.volume-10)}}))}><Text style={S.filterText}>−10</Text></Pressable><View style={{flex:1,justifyContent:'center'}}><View style={{height:8,borderRadius:10,backgroundColor:'#d9dce6'}}><View style={{height:8,width:`${state.sounds?.volume??35}%`,borderRadius:10,backgroundColor:P.blue}}/></View></View><Pressable style={S.filter} onPress={()=>update(v=>({...v,sounds:{...v.sounds,volume:Math.min(100,v.sounds.volume+10)}}))}><Text style={S.filterText}>+10</Text></Pressable></View>{([['buttons','Sons nos botões'],['series','Série marcada'],['finish','Treino finalizado'],['rest','Descanso concluído'],['countdown','Contagem 3, 2, 1'],['voice','Voz em português (ou bipes)']] as const).map(([key,label])=><Pressable key={key} style={S.soundSwitch} onPress={()=>update(v=>({...v,sounds:{...v.sounds,[key]:!v.sounds[key]}}))}><Text style={S.settingTitle}>{label}</Text><Text style={S.soundState}>{state.sounds?.[key]?'SIM ✓':'NÃO'}</Text></Pressable>)}<Text style={S.muted}>Todos os efeitos podem ser silenciados com um toque. A biblioteca funciona offline e é independente das playlists.</Text></View><View style={S.settingBox}><Text style={S.settingTitle}>ILUSTRAÇÕES SEM ERRO DE IDENTIDADE</Text><Text style={S.muted}>Sem imagem da Camila? Usamos Josperd e mostramos um aviso. Sem a imagem de qualquer personagem para um exercício? Exibimos “Imagem indisponível”.</Text></View><View style={S.settingBox}><Text style={S.settingTitle}>ATUALIZAÇÕES DO GITHUB</Text><Text style={S.muted}>{`Repositório: ${GITHUB_REPO}`}</Text><Text style={S.muted}>{releaseStatus}</Text><Btn subtle text={state.notifyUpdates?'AVISOS ATIVOS (TOQUE PARA DESATIVAR)':'AVISOS DESATIVADOS (TOQUE PARA ATIVAR)'} onPress={()=>update(v=>({...v,notifyUpdates:!v.notifyUpdates}))}/><Btn subtle text="VERIFICAR ATUALIZAÇÃO AGORA" onPress={()=>checkGithub(true)}/><Btn subtle text="VER TODAS AS VERSÕES" onPress={()=>Linking.openURL(`https://github.com/${GITHUB_REPO}/releases`)}/></View><View style={S.settingBox}><Text style={S.settingTitle}>BACKUP DOS SEUS DADOS</Text><Text style={S.muted}>Exporte um arquivo com seus treinos, cargas e histórico. Importe-o para restaurar neste ou em outro aparelho. Nada é enviado a servidores.</Text><Btn subtle text="EXPORTAR BACKUP (JSON)" onPress={exportBackup}/><Btn subtle text="EXPORTAR PLANILHA (CSV)" onPress={exportCsv}/><Btn subtle text="IMPORTAR BACKUP" onPress={importBackup}/></View><View style={S.settingBox}><Text style={S.settingTitle}>ARMAZENAMENTO LOCAL</Text><Text style={S.muted}>Os registros são salvos somente neste dispositivo por meio de AsyncStorage. Seu navegador e o aplicativo nativo não sincronizam dados entre si.</Text></View><Btn subtle text="APAGAR HISTÓRICO E AJUSTES" onPress={()=>Alert.alert('Apagar tudo?','Seus treinos e preferências locais serão apagados.',[{text:'Cancelar',style:'cancel'},{text:'Apagar',style:'destructive',onPress:()=>setState(INITIAL)}])}/><Text style={S.brandSignature}>MODO TREINO · BY JOSPERD · 2026</Text></>;
